import type { SourcedQuote } from './quoteTypes';

/**
 * A second, independently sourced collection. Translations are original renderings
 * of the public-domain Arabic, not copied from a modern published translation.
 * Adaptations include reflection and are never presented as a speaker's exact words.
 * Companion entries explicitly concern reported speech/conduct in the cited account.
 * Arabic texts and narrative contexts checked at Quran.com/Sunnah.com, 2026-09-22.
 */
type Draft = Omit<SourcedQuote, 'id'>;
type Kind = SourcedQuote['kind'];
const q = (kind: Kind, reference: string, sura: string, tr: string, text: string, tags: string[], excerpt = false, url?: string): Draft => ({
  kind, reference, tr, text, category: 'faith', tags: ['quran', ...tags],
  source: `Quran ${reference}${excerpt ? ' · excerpt' : ''}`,
  sourceTr: `Kur’an, ${sura} ${reference}${excerpt ? ' · ayetten bölüm' : ''}`,
  sourceUrl: url ?? `https://quran.com/${reference.replace(':', '/')}`,
});
const c = (name: string, nameTr: string, collection: 'bukhari' | 'muslim', reference: string, tr: string, text: string, tags: string[]): Draft => ({
  kind: 'adaptation', reference, tr, text, category: 'faith', tags: ['sahaba', ...tags],
  source: `${name} · reported words/conduct · ${collection === 'bukhari' ? 'Bukhari' : 'Muslim'} ${reference}`,
  sourceTr: `${nameTr} · rivayetteki söz ve davranışı · ${collection === 'bukhari' ? 'Buhârî' : 'Müslim'} ${reference}`,
  sourceUrl: `https://sunnah.com/${collection}:${reference}`,
});
const h = (kind: Kind, collection: 'bukhari' | 'muslim', reference: string, tr: string, text: string, tags: string[], excerpt = false, conduct = false): Draft => ({
  kind, reference, tr, text, category: 'faith', tags: ['hadith', ...tags],
  source: `Prophet Muhammad${conduct ? ' · reported conduct' : ''} · ${collection === 'bukhari' ? 'Bukhari' : 'Muslim'} ${reference}${excerpt ? ' · excerpt' : ''}`,
  sourceTr: `Hz. Muhammed${conduct ? ' · rivayetteki davranışı' : ''} · ${collection === 'bukhari' ? 'Buhârî' : 'Müslim'} ${reference}${excerpt ? ' · hadisten bölüm' : ''}`,
  sourceUrl: `https://sunnah.com/${collection}:${reference}`,
});

